import { createRequire } from 'node:module';
import { firefox } from 'playwright-core';

const require = createRequire(import.meta.url);
console.log('Playwright', require('playwright-core/package.json').version);
console.log('Firefox executable', firefox.executablePath());
const html = '<span id="l">Save</span><button id="b" aria-labelledby="l"></button>';
let failures = 0;
for (const scenario of ['same-world control', 'main world then role locator', 'role locator then main world']) {
  const browser = await firefox.launch({ headless: true });
  const page = await browser.newPage();
  page.setDefaultTimeout(10000);
  let crashed = false;
  page.on('crash', () => { crashed = true; });
  try {
    await page.setContent(html);
    const readMain = () => page.evaluate(() => document.getElementById('b').ariaLabelledByElements.length);
    const readRole = () => page.getByRole('button', { name: 'Save' }).click({ trial: true });
    if (scenario === 'same-world control') {
      await readMain();
      await readMain();
    } else if (scenario === 'main world then role locator') {
      await readMain();
      await readRole();
    } else {
      await readRole();
      await readMain();
    }
    console.log(JSON.stringify({ scenario, result: 'PASS', crashed }));
  } catch (error) {
    failures++;
    console.log(JSON.stringify({ scenario, result: 'FAIL', crashed, error: error.message }));
  } finally {
    await browser.close();
  }
}
process.exitCode = failures ? 1 : 0;
